import React, { useEffect, useState } from 'react';

export default function UserProfileCard({ token, setMsg }) {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!token) { setLoading(false); return; }

    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/dashboard/user-summary', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(d => { setSummary(d); setLoading(false); })
      .catch(err => { console.error(err); setLoading(false); });
  }, [token]);

  if (loading) {
    return <div style={{ padding: 12, textAlign: 'center', color: '#666' }}>Loading profile...</div>;
  }

  if (!summary) {
    return <div style={{ padding: 12, textAlign: 'center', color: '#999' }}>No profile data</div>;
  }

  const roleColors = {
    Admin: '#ef4444',
    NGO: '#3b82f6',
    volunteer: '#10b981',
    donor: '#f59e0b'
  };

  const roleColor = roleColors[summary.role] || '#6b7280';

  return (
    <div style={{
      background: '#fff',
      borderRadius: 14,
      padding: 16,
      boxShadow: '0 10px 30px rgba(0,0,0,0.08)',
      border: '1px solid #f1f5f9'
    }}>
      {/* HEADER: icon + name/role */}
      <div style={{ display: 'flex', gap: 12, alignItems: 'center', marginBottom: 14 }}>
        <div style={{
          width: 50,
          height: 50,
          borderRadius: 50,
          background: roleColor,
          color: '#fff',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontWeight: 800,
          fontSize: 20,
          boxShadow: `0 4px 12px ${roleColor}40`
        }}>
          {summary.name?.charAt(0).toUpperCase() || '?'}
        </div>

        <div>
          <div style={{ fontWeight: 700, fontSize: 16, color: '#111' }}>{summary.name}</div>
          <div style={{
            fontSize: 12,
            fontWeight: 600,
            color: '#fff',
            background: roleColor,
            display: 'inline-block',
            padding: '3px 10px',
            borderRadius: 6,
            marginTop: 4
          }}>
            {summary.role}
          </div>
        </div>
      </div>

      {/* EMAIL */}
      <div style={{ fontSize: 13, color: '#666', marginBottom: 12 }}>
        <span style={{ fontWeight: 600 }}>Email:</span> {summary.email}
      </div>

      {/* POINTS (always show) */}
      <div style={{
        background: 'linear-gradient(135deg, #0ea5e9, #6366f1)',
        color: '#fff',
        padding: 12,
        borderRadius: 10,
        textAlign: 'center',
        marginBottom: 12,
        boxShadow: '0 6px 18px rgba(6,182,212,0.2)'
      }}>
        <div style={{ fontSize: 24, fontWeight: 800 }}>{summary.points || 0}</div>
        <div style={{ fontSize: 11, opacity: 0.9, marginTop: 4 }}>TOTAL POINTS</div>
      </div>

      {/* ROLE-SPECIFIC STATS */}
      {summary.role === 'Admin' && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
          <div style={{ background: '#f3f4f6', padding: 10, borderRadius: 8, textAlign: 'center' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#1f2937' }}>{summary.totalUsers}</div>
            <div style={{ fontSize: 11, color: '#6b7280', marginTop: 4 }}>Users</div>
          </div>
          <div style={{ background: '#f3f4f6', padding: 10, borderRadius: 8, textAlign: 'center' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#1f2937' }}>{summary.totalEvents}</div>
            <div style={{ fontSize: 11, color: '#6b7280', marginTop: 4 }}>Events</div>
          </div>
          <div style={{ background: '#f3f4f6', padding: 10, borderRadius: 8, textAlign: 'center', gridColumn: '1/-1' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#1f2937' }}>{summary.totalVolunteers}</div>
            <div style={{ fontSize: 11, color: '#6b7280', marginTop: 4 }}>Volunteers</div>
          </div>
        </div>
      )}

      {summary.role === 'NGO' && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
          <div style={{ background: '#dbeafe', padding: 10, borderRadius: 8, textAlign: 'center', border: '1px solid #93c5fd' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#1e40af' }}>{summary.eventsHosted}</div>
            <div style={{ fontSize: 11, color: '#1e40af', marginTop: 4 }}>Events Hosted</div>
          </div>
          <div style={{ background: '#dbeafe', padding: 10, borderRadius: 8, textAlign: 'center', border: '1px solid #93c5fd' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#1e40af' }}>{summary.volunteerCount}</div>
            <div style={{ fontSize: 11, color: '#1e40af', marginTop: 4 }}>Volunteers</div>
          </div>
          <div style={{ background: '#dbeafe', padding: 10, borderRadius: 8, textAlign: 'center', border: '1px solid #93c5fd', gridColumn: '1/-1' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#1e40af' }}>₹{summary.totalDonated.toFixed(0)}</div>
            <div style={{ fontSize: 11, color: '#1e40af', marginTop: 4 }}>Donations Received</div>
          </div>
        </div>
      )}

      {summary.role !== 'Admin' && summary.role !== 'NGO' && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
          <div style={{ background: '#dcfce7', padding: 10, borderRadius: 8, textAlign: 'center', border: '1px solid #86efac' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#166534' }}>{summary.volunteerCount}</div>
            <div style={{ fontSize: 11, color: '#166534', marginTop: 4 }}>Volunteered</div>
          </div>
          <div style={{ background: '#fef3c7', padding: 10, borderRadius: 8, textAlign: 'center', border: '1px solid #fcd34d' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#92400e' }}>{summary.donationCount}</div>
            <div style={{ fontSize: 11, color: '#92400e', marginTop: 4 }}>Donated</div>
          </div>
          <div style={{ background: '#f3e8ff', padding: 10, borderRadius: 8, textAlign: 'center', border: '1px solid #e9d5ff', gridColumn: '1/-1' }}>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#6b21a8' }}>₹{summary.totalDonated.toFixed(0)}</div>
            <div style={{ fontSize: 11, color: '#6b21a8', marginTop: 4 }}>Total Donated</div>
          </div>
        </div>
      )}
    </div>
  );
}
